package fraymus.workspace;

import org.json.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;

/** Prospective same-world recovery comparison; full costs, failures and original motion retained. */
final class RecoveryStudy066 {
    static final String PROTOCOL="bounded-observation-replan-066-v1";
    static final int TOTAL=364;
    private static final class Identity {static final String VALUE=implementation();}
    static String source(){return Identity.VALUE;}
    private static String implementation(){var b=new StringBuilder(PROTOCOL).append(RecoveryTrial066.source());try(var in=RecoveryStudy066.class.getResourceAsStream("RecoveryStudy066.class")){b.append(MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return MeasurementStore.hash(b.toString());}
    static JSONArray cases(boolean shifted){var random=new Random(shifted?66002:66001);var out=new JSONArray();for(int regime=0;regime<2;regime++)for(int i=0;i<(shifted?6:30);i++){double angle=12+20*random.nextDouble(),ratio=regime==0?.85+.14*random.nextDouble():1.01+.19*random.nextDouble(),center=.02+.34*random.nextDouble();if(shifted)switch(i%3){case 0->angle=10;case 1->angle=34;case 2->ratio=1;}
        out.put(new JSONObject().put("angleDeg",angle).put("frictionRatio",ratio).put("centerM",center).put("halfWidthM",new double[]{.012,.024,.045}[i%3]));}return out;}
    static JSONArray parityCases(){var out=new JSONArray();for(double[] a:new double[][]{{14,.90,.08},{30,.98,.38},{14,1.05,.08},{30,1.18,.38}})out.put(Stopping063.definition(a[0],a[1],a[2]));return out;}
    static JSONObject manifest(){return new JSONObject().put("protocol",PROTOCOL).put("source",source()).put("nativeSource",RecoveryTrial066.source()).put("model",Calibration065.info()).put("tasks",cases(false)).put("shifted",cases(true)).put("parityCases",parityCases()).put("methods",new JSONArray(RecoveryPolicy066.METHODS)).put("decisionTick",60).put("maximumCorrectionMps",.16).put("maximumTangentMps",.8).put("maximumRotationDeg",10).put("maximumNormalMps",.1).put("maximumAngularRadps",2).put("successReward",1).put("missCost",2).put("refusalCost",.15).put("actionCost",.02).put("observationCost",.03).put("replanCost",.01).put("gainFixedAndPooled",.10).put("gainBlind",.05).put("minimumSuccessRate",.5).put("maximumMissRate",.2).put("minimumRecoveryRate",.3).put("total",TOTAL).put("controllerAuthority",false);}
    static JSONObject evaluation(JSONArray rows){var e=RecoveryPolicy066.evaluate(rows,true);var groups=new JSONObject();for(String key:List.of("accelerating","slowing","width12mm","width24mm","width45mm")){var subset=new JSONArray();for(Object raw:rows){var task=((JSONObject)raw).getJSONObject("task");boolean match=switch(key){case "accelerating"->task.getDouble("frictionRatio")<1;case "slowing"->task.getDouble("frictionRatio")>1;default->Math.abs(task.getDouble("halfWidthM")-(key.equals("width12mm")?.012:key.equals("width24mm")?.024:.045))<1e-12;};if(match)subset.put(raw);}groups.put(key,RecoveryPolicy066.evaluate(subset,false));}return e.put("subgroups",groups).put("qualified",qualifies(e)).put("proposed","observed").put("controllerAuthority",false).put("meaning","Empirical native task utility after declared assumed costs; timings are machine-specific diagnostics, not qualification or physical calibration");}
    static boolean qualifies(JSONObject e){var p=e.getJSONObject("pairedObservedMinus");var observed=e.getJSONObject("methods").getJSONObject("observed");return p.getJSONObject("fixed").getDouble("meanDelta")>=.10&&p.getJSONObject("pooled").getDouble("meanDelta")>=.10&&p.getJSONObject("blind").getDouble("meanDelta")>=.05&&observed.getDouble("allTaskSuccessRate")>=.5&&observed.getDouble("allTaskMissRate")<=.2&&observed.optDouble("recoveryRate",0)>=.3;}
    static JSONObject parityTask(JSONObject c){return new JSONObject().put("angleDeg",c.getDouble("angleDeg")).put("frictionRatio",c.getDouble("frictionRatio")).put("centerM",.1).put("halfWidthM",.045);}
    static JSONObject parityDecision(JSONObject c){return new JSONObject().put("method","simple").put("execute",true).put("recover",false).put("speedMps",c.getDouble("pushMps"));}
    static void run(JSONObject job,Path dir,Runnable cancel,FraynixOutcome061.Progress progress)throws Exception{
        job.put("manifest066",manifest()).put("parity066",new JSONArray()).put("tasks066",new JSONArray()).put("shifted066",new JSONArray()).put("progress",0).put("total",TOTAL).put("nativeExecutions",0);progress.save("Bounded recovery contract retained");
        for(Object raw:parityCases()){cancel.run();var c=(JSONObject)raw;var old=Stopping063.trial(c,"baseline",180,4,dir,cancel);var now=RecoveryTrial066.run(parityTask(c),parityDecision(c),dir,cancel,partial->{});double error=RecoveryTrial066.parity(old,now);job.getJSONArray("parity066").put(new JSONObject().put("definition",c).put("original",old).put("adapter",now).put("maximumDelta",error));job.put("nativeExecutions",job.getInt("nativeExecutions")+2).put("progress",job.getInt("progress")+1);progress.save("Original runtime parity retained");if(error>1e-6)throw new IllegalStateException("New adapter changed original native motion");}
        for(boolean shifted:new boolean[]{false,true})for(Object raw:cases(shifted)){cancel.run();var task=(JSONObject)raw;var row=new JSONObject().put("task",task).put("plannedAt",Instant.now().toString()).put("plan",RecoveryPolicy066.initial(task)).put("results",new JSONObject());job.getJSONArray(shifted?"shifted066":"tasks066").put(row);progress.save("Five initial plans saved before outcomes");
            for(String method:RecoveryPolicy066.METHODS){cancel.run();var decision=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);var result=new JSONObject();row.getJSONObject("results").put(method,result);JSONObject record=null;
                if(decision.getBoolean("execute")){
                    record=RecoveryTrial066.run(task,decision,dir,cancel,partial->{result.put("pending",partial);progress.save(method+": tick60 state and correction saved before action");});result.remove("pending");result.put("record",record);job.put("nativeExecutions",job.getInt("nativeExecutions")+1);
                }
                result.put("outcome",RecoveryPolicy066.outcome(task,decision,record));job.put("progress",job.getInt("progress")+1);progress.save(method+": actual outcome and cost retained");
            }
        }
        job.put("evaluation066",evaluation(job.getJSONArray("tasks066"))).put("shiftedEvaluation066",RecoveryPolicy066.evaluate(job.getJSONArray("shifted066"),true));boolean qualified=job.getJSONObject("evaluation066").getBoolean("qualified");job.put("accepted",qualified).put("reason",qualified?"Observed recovery passed declared utility gate; no controller promotion":"Observed recovery did not pass declared utility gate; all failures and costs retained");audit(job);progress.save("Bounded recovery comparison verified");
    }
    static void audit(JSONObject job){
        if(!manifest().similar(job.getJSONObject("manifest066")))throw new IllegalStateException("Recovery contract differs");var ids=new HashSet<String>();int count=0;var parity=job.getJSONArray("parity066");if(parity.length()!=4)throw new IllegalStateException("Parity checks incomplete");for(int i=0;i<4;i++){var row=parity.getJSONObject(i);var c=parityCases().getJSONObject(i);var old=row.getJSONObject("original");var now=row.getJSONObject("adapter");double error=RecoveryTrial066.parity(old,now);if(!c.similar(row.getJSONObject("definition"))||!c.similar(old.getJSONObject("definition"))||!parityTask(c).similar(now.getJSONObject("task"))||!parityDecision(c).similar(now.getJSONObject("decision"))||error>1e-6||error!=row.getDouble("maximumDelta")||!ids.add(old.getString("id"))||!ids.add(now.getString("id")))throw new IllegalStateException("Parity evidence changed");count+=2;}
        for(boolean shifted:new boolean[]{false,true}){var rows=job.getJSONArray(shifted?"shifted066":"tasks066");var expected=cases(shifted);if(rows.length()!=expected.length())throw new IllegalStateException("Recovery task set incomplete");for(int i=0;i<rows.length();i++){var row=rows.getJSONObject(i);var task=expected.getJSONObject(i);if(!task.similar(row.getJSONObject("task"))||!RecoveryPolicy066.initial(task).similar(row.getJSONObject("plan")))throw new IllegalStateException("Initial recovery plan differs");Instant planned=Instant.parse(row.getString("plannedAt"));var results=row.getJSONObject("results");if(!results.keySet().equals(new HashSet<>(RecoveryPolicy066.METHODS)))throw new IllegalStateException("Policy result missing or extra");for(String method:RecoveryPolicy066.METHODS){var result=results.getJSONObject(method);if(result.has("pending"))throw new IllegalStateException("Recovery still pending");var decision=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);var record=result.optJSONObject("record");if(decision.getBoolean("execute")){if(shifted||record==null)throw new IllegalStateException("Unsupported or missing native execution");RecoveryTrial066.verify(record);if(!record.getJSONObject("task").similar(task)||!record.getJSONObject("decision").similar(decision)||!ids.add(record.getString("id"))||Instant.parse(record.getString("startedAt")).isBefore(planned))throw new IllegalStateException("Native identity or prior plan changed");count++;}else if(result.has("record"))throw new IllegalStateException("Refusal fabricates native evidence");if(!RecoveryPolicy066.outcome(task,decision,record).similar(result.getJSONObject("outcome")))throw new IllegalStateException("Recovery outcome or cost changed");}}}
        if(job.getInt("progress")!=TOTAL||job.getInt("total")!=TOTAL||job.getInt("nativeExecutions")!=count||!evaluation(job.getJSONArray("tasks066")).similar(job.getJSONObject("evaluation066"))||!RecoveryPolicy066.evaluate(job.getJSONArray("shifted066"),true).similar(job.getJSONObject("shiftedEvaluation066"))||job.getBoolean("accepted")!=job.getJSONObject("evaluation066").getBoolean("qualified"))throw new IllegalStateException("Recovery evaluation/counts differ");
    }
    static JSONObject summary(JSONObject j){var out=new JSONObject().put("jobId",j.getString("id")).put("status",j.getString("status")).put("nativeExecutions",j.optInt("nativeExecutions")).put("model",Calibration065.info());if(j.has("evaluation066"))out.put("evaluation",j.getJSONObject("evaluation066")).put("shiftedEvaluation",j.getJSONObject("shiftedEvaluation066"));return out;}
}
